import React from 'react'
import Barcode from 'react-barcode'
import './BarcodePrint.css'
import Moment from 'react-moment'

const BarcodePrintMultiple = React.forwardRef(({ barcode, rmName }, ref) => {
    return (
        <div ref={ref}>
            {barcode.map((value, index) => {
                return (
                    <div
                        key={index}
                        className="flex flex-col justify-center items-center"
                    >
                        <p className="text-black text-[6px] font-normal mb-0 mt-0 grid grid-col-1 gap-0">
                            <span>Raw Material Name : {rmName}</span>
                            <span className="grid grid-cols-2 gap-x-2 gap-y-0">
                                <span>
                                    Gross Weight : {value.gross_weight}KG
                                </span>
                                <span>Net Weight : {value.net_weight}KG</span>
                                <span>
                                    Exp Date :
                                    <Moment format="DD-MM-YYYY">
                                        {value.expiry_date}
                                    </Moment>
                                </span>
                            </span>
                        </p>
                        <Barcode
                            width={1.2}
                            height={36}
                            type="Code128"
                            value={value.barcode == '' ? '' : value.barcode}
                            fontSize={10}
                            marginBottom={25}
                        />
                    </div>
                )
            })}
        </div>
    )
})

export default React.memo(BarcodePrintMultiple)
