import React from 'react'
import Barcode from 'react-barcode'
import './BarcodePrint.css'
import Moment from 'react-moment'

const BarcodePrint = React.forwardRef(({ value, rmName }, ref) => {
    return (
        <div className="flex flex-col justify-center items-center" ref={ref}>
            <p className="text-black text-[5px] font-bold mb-0 mt-2 grid grid-col-1 gap-0">
                <span>Raw Material Name : {rmName}</span>
                <span className="grid grid-cols-3 gap-x-2 gap-y-0">
                    <span>
                        Exp Date :
                        <Moment format="DD-MM-YYYY">{value.expiry_date}</Moment>
                    </span>
                    <span>Gross Weight : {value.gross_weight}KG</span>
                    <span>Net Weight : {value.net_weight}KG</span>
                </span>
            </p>
            <Barcode
                width={1}
                height={48}
                type="Code128"
                value={value.barcode == '' ? '' : value.barcode}
                fontSize={12}
            />
        </div>
    )
})

export default BarcodePrint
